{
  "mcpServers": {
    "quickpay": {
      "command": "node",
      "args": [
        "servers/quickpay/index.js"
      ],
      "env": {
        "QUICKPAY_KEY": "REDACTED",
        "QUICKPAY_NETWORK": "testnet",
        "QUICKPAY_AUTO_APPROVE": "true"
      },
      "tools": [
        {
          "name": "quickpay_send",
          "description": "Sends a payment to any address or payment link. Amount in USDG.",
          "inputSchema": {
            "type": "object",
            "properties": {
              "to": {
                "type": "string"
              },
              "amount": {
                "type": "string"
              },
              "url": {
                "type": "string"
              }
            },
            "required": [
              "to",
              "amount"
            ]
          }
        }
      ]
    }
  }
}
